export const dashboardHtml: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Bobby Stage</title>\n<style>\n:root {\n  --bg: #f4f2ee; --panel: #ffffff; --ink: #1b1d22; --muted: #6b6f78; --line: #e2dfd8;\n  --accent: #2f6df6; --accent-soft: #e4ecff; --ok: #1f9d55; --ok-soft: #dcf3e5;\n  --bad: #d64545; --bad-soft: #fbe3e3; --warn: #c98a00; --you: #efece6; --bobby: #e4ecff;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0f1115; --panel: #171a21; --ink: #eef0f4; --muted: #9298a5; --line: #262b35;\n    --accent: #6d9bff; --accent-soft: #1b2742; --ok: #3ccf7f; --ok-soft: #133324;\n    --bad: #ff6b6b; --bad-soft: #3a1a1c; --warn: #f2b84b; --you: #222630; --bobby: #1b2742;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0f1115; --panel: #171a21; --ink: #eef0f4; --muted: #9298a5; --line: #262b35;\n  --accent: #6d9bff; --accent-soft: #1b2742; --ok: #3ccf7f; --ok-soft: #133324;\n  --bad: #ff6b6b; --bad-soft: #3a1a1c; --warn: #f2b84b; --you: #222630; --bobby: #1b2742;\n}\n* { box-sizing: border-box; }\n[hidden] { display: none !important; }\nhtml, body { margin: 0; height: 100%; }\nbody {\n  background: var(--bg); color: var(--ink);\n  font: 18px/1.4 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  display: grid; grid-template-rows: auto 1fr; gap: 16px; padding: 16px 20px;\n}\nheader { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }\n.brand { font-size: 32px; font-weight: 800; letter-spacing: -0.02em; }\n.brand span { color: var(--accent); }\n#task { flex: 1; min-width: 240px; display: flex; align-items: baseline; gap: 14px; }\n#task-title { font-size: 28px; font-weight: 700; }\n.badge { font-size: 15px; font-weight: 700; padding: 3px 12px; border-radius: 999px;\n  text-transform: uppercase; letter-spacing: 0.06em; background: var(--line); color: var(--muted); }\n.badge.started { background: var(--accent-soft); color: var(--accent); }\n.badge.done { background: var(--ok-soft); color: var(--ok); }\n.badge.failed, .badge.cancelled { background: var(--bad-soft); color: var(--bad); }\n#peers { display: flex; gap: 14px; font-size: 16px; color: var(--muted); }\n.peer { display: flex; align-items: center; gap: 6px; }\n.dot { width: 12px; height: 12px; border-radius: 50%; background: var(--line); }\n.peer.on .dot { background: var(--ok); box-shadow: 0 0 8px var(--ok); }\n.peer.on { color: var(--ink); }\n#conn { font-size: 14px; color: var(--muted); }\n#conn.live { color: var(--ok); }\n#conn.down { color: var(--bad); }\n\nmain { display: grid; gap: 16px; min-height: 0;\n  grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr) auto minmax(0, 1fr);\n  grid-template-areas: \"talk plan phone feed\"; }\nbody.no-phone main { grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr) minmax(0, 1fr);\n  grid-template-areas: \"talk plan feed\"; }\n.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 14px;\n  padding: 16px 18px; display: flex; flex-direction: column; min-height: 0; }\n.panel h2 { margin: 0 0 12px; font-size: 14px; text-transform: uppercase; letter-spacing: 0.1em; color: var(--muted); }\n.scroll { overflow-y: auto; min-height: 0; flex: 1; }\n#talk-panel { grid-area: talk; }\n#plan-panel { grid-area: plan; }\n#side { grid-area: feed; display: flex; flex-direction: column; gap: 16px; min-height: 0; }\n#feed-panel { flex: 1; }\n.empty { color: var(--muted); font-style: italic; }\n\n/* Conversation */\n#talk { display: flex; flex-direction: column; gap: 10px; }\n.line { max-width: 92%; padding: 10px 14px; border-radius: 14px; font-size: 20px; animation: pop .25s ease-out; }\n.line .who { display: block; font-size: 14px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin-bottom: 2px; }\n.line.you { align-self: flex-end; background: var(--you); border-bottom-right-radius: 4px; }\n.line.bobby { align-self: flex-start; background: var(--bobby); border-bottom-left-radius: 4px; }\n.line.sys { align-self: center; background: none; padding: 2px; font-size: 14px; color: var(--muted); }\n@keyframes pop { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n\n/* Plan */\n#plan ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.step { display: grid; grid-template-columns: 44px 1fr; gap: 14px; align-items: start;\n  padding: 14px 16px; border-radius: 12px; border: 2px solid transparent; transition: background .3s, border-color .3s, opacity .3s; }\n.step .mark { width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center;\n  font-weight: 800; font-size: 18px; background: var(--line); color: var(--muted); }\n.step .do { font-size: 26px; font-weight: 700; line-height: 1.2; }\n.step .why { font-size: 18px; color: var(--muted); margin-top: 2px; }\n.step .why::before { content: \"why: \"; font-weight: 700; }\n.step.running { background: var(--accent-soft); border-color: var(--accent); }\n.step.running .mark { background: var(--accent); color: #fff; animation: pulse 1.2s ease-in-out infinite; }\n.step.done { opacity: .62; }\n.step.done .mark { background: var(--ok); color: #fff; }\n.step.failed .mark { background: var(--bad); color: #fff; }\n.step.changed { box-shadow: 0 0 0 3px var(--warn); }\n.plan-note { font-size: 15px; color: var(--warn); font-weight: 700; margin: 0 0 8px; }\n@keyframes pulse { 50% { box-shadow: 0 0 0 8px transparent; transform: scale(1.08); } }\n\n/* Phone feed */\n#feed { display: flex; flex-direction: column; gap: 8px; }\n.act { display: grid; grid-template-columns: 28px 1fr; gap: 10px; align-items: baseline; font-size: 20px; animation: pop .25s ease-out; }\n.act .res { font-weight: 800; text-align: center; color: var(--muted); }\n.act.ok .res { color: var(--ok); }\n.act.fail .res { color: var(--bad); }\n.act.fail .what::after { content: attr(data-err); display: block; font-size: 14px; color: var(--bad); }\n.act.pending .what { font-weight: 700; }\n.act.note { font-size: 16px; color: var(--muted); }\n.act.note .res { color: var(--warn); }\n\n/* Call */\n#call-panel { border-color: var(--accent); }\n#call .status { font-size: 24px; font-weight: 700; display: flex; align-items: center; gap: 10px; }\n#call .status.live::before { content: \"\"; width: 12px; height: 12px; border-radius: 50%; background: var(--bad); animation: blink 1s infinite; }\n#call .number { color: var(--muted); font-size: 15px; margin-top: 2px; }\n#call .summary { font-size: 22px; margin-top: 10px; padding: 10px 12px; background: var(--ok-soft); border-radius: 10px; }\n#call .summary.failed { background: var(--bad-soft); }\n#call .tx { margin-top: 10px; font-size: 15px; color: var(--muted); display: grid; gap: 4px; max-height: 9em; overflow-y: auto; }\n#call .tx b { color: var(--ink); }\n@keyframes blink { 50% { opacity: .25; } }\n\n#rec { font: inherit; font-size: 14px; font-weight: 700; padding: 4px 12px; border-radius: 999px;\n  border: 1px solid var(--line); background: var(--panel); color: var(--muted); cursor: pointer; }\n.in-app #rec { display: none; }\n#rec.on { color: #fff; background: var(--bad); border-color: var(--bad); }\n/* Voice-cursor sync strip */\n#sync { display: flex; flex-direction: column; gap: 6px; }\n.sync-row { display: grid; grid-template-columns: minmax(0, 1fr) 58px; grid-template-areas: \"label label\" \"bar gap\";\n  column-gap: 10px; row-gap: 2px; align-items: center; font-size: 15px; padding-bottom: 4px; border-bottom: 1px solid var(--line); }\n.sync-row .label { grid-area: label; overflow-wrap: anywhere; }\n.sync-row .sync-bar { grid-area: bar; }\n.sync-row .gap { grid-area: gap; }\n.sync-bar { position: relative; height: 14px; background: var(--line); border-radius: 7px; }\n.sync-bar i { position: absolute; top: 2px; height: 10px; border-radius: 5px; }\n.sync-bar .voice { background: var(--accent); }\n.sync-bar .cursor { background: var(--ok); opacity: .8; }\n.sync-row .gap { font-weight: 800; text-align: right; font-variant-numeric: tabular-nums; }\n.sync-row.good .gap { color: var(--ok); }\n.sync-row.off .gap { color: var(--warn); }\n.sync-legend { font-size: 14px; color: var(--muted); margin: -6px 0 8px; }\n.sync-legend b.v { color: var(--accent); } .sync-legend b.c { color: var(--ok); }\n\n/* Phone panel (experiment): latest screen_result + the cursor at each act target */\n#phone-panel { grid-area: phone; padding: 16px 14px; align-items: center; }\nbody.no-phone #phone-panel { display: none; }\n.phone { position: relative; height: 100%; max-height: 100%; aspect-ratio: 1080 / 2400; min-height: 0;\n  border: 10px solid #1b1d22; border-radius: 34px; background: #0d0f13; box-shadow: 0 6px 24px rgba(0,0,0,.18); overflow: hidden; }\n.phone .app { position: absolute; top: 0; left: 0; right: 0; z-index: 3; padding: 8px 10px 4px; font-size: 14px; font-weight: 700;\n  color: #cfd3dc; background: linear-gradient(#0d0f13, rgba(13,15,19,0)); text-align: center; letter-spacing: .04em; }\n.phone .screen { position: absolute; inset: 0; transition: opacity .25s; }\n.phone .screen.stale { opacity: .3; }\n.phone .screen.has-image { background-size: 100% 100%; background-repeat: no-repeat; }\n.phone .screen.has-image .node { background: rgba(13,15,19,.35); border-color: rgba(109,155,255,.7); color: transparent; }\n.phone .screen.has-image .node.hit { background: rgba(109,155,255,.35); }\n.node { position: absolute; border: 1px solid rgba(255,255,255,.22); border-radius: 6px; color: #e9ecf2;\n  font-size: 14px; line-height: 1.15; padding: 2px 4px; overflow: hidden; display: flex; align-items: center; justify-content: center;\n  text-align: center; overflow-wrap: normal; word-break: normal; background: rgba(255,255,255,.05); }\n.node.tap { border-color: rgba(109,155,255,.55); }\n.node.edit { border-style: dashed; justify-content: flex-start; text-align: left; }\n.node.tiny { overflow: visible; color: transparent; }\n.phone .cap { position: absolute; z-index: 2; font-size: 14px; line-height: 1.2; color: #e9ecf2; background: rgba(13,15,19,.92);\n  padding: 1px 6px; border-radius: 5px; white-space: nowrap; pointer-events: none; transform: translateX(-50%); }\n.node.hint { font-style: italic; color: #9aa1ae; }\n.node.hit { background: rgba(109,155,255,.35); border-color: #6d9bff; }\n.phone .cursor { position: absolute; z-index: 5; width: 44px; height: 44px; margin: -22px 0 0 -22px; left: 50%; top: 55%;\n  transition: left .65s cubic-bezier(.45,.05,.25,1), top .65s cubic-bezier(.45,.05,.25,1), opacity .4s; opacity: 0; pointer-events: none; }\n.phone .cursor.on { opacity: 1; }\n.phone .cursor img { width: 100%; height: 100%; display: block; }\n.phone .ripple { position: absolute; z-index: 4; width: 20px; height: 20px; margin: -10px 0 0 -10px; border-radius: 50%;\n  border: 3px solid #6d9bff; animation: ripple .6s ease-out forwards; pointer-events: none; }\n@keyframes ripple { to { transform: scale(3.2); opacity: 0; } }\n.phone .chip { position: absolute; z-index: 6; left: 50%; transform: translateX(-50%); bottom: 8%; max-width: 88%;\n  background: rgba(255,255,255,.94); color: #1b1d22; font-size: 15px; font-weight: 700; padding: 6px 10px; border-radius: 10px;\n  width: max-content; text-align: center; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; animation: pop .25s ease-out; }\n.phone .empty-screen { position: absolute; inset: 0; display: grid; place-items: center; color: #7d8390; font-size: 13px; font-style: italic; padding: 12px; text-align: center; }\n@media (max-width: 900px) {\n  body { padding: 12px 16px; height: auto; }\n  html, body { height: auto; }\n  main, body.no-phone main { grid-template-columns: minmax(0, 1fr); grid-template-areas: \"plan\" \"phone\" \"talk\" \"feed\"; }\n  .phone { height: 70vh; }\n  .scroll { max-height: 60vh; }\n  .brand { font-size: 26px; } #task-title { font-size: 22px; }\n  .step { grid-template-columns: 34px 1fr; padding: 10px 12px; } .step .mark { width: 32px; height: 32px; font-size: 15px; }\n  .step .do { font-size: 20px; } .step .why, .line, .act { font-size: 16px; }\n}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"brand\">Bobby<span>.</span></div>\n  <div id=\"task\"><span id=\"task-title\" class=\"empty\">Waiting for a task</span><span id=\"task-status\"></span></div>\n  <div id=\"peers\"></div>\n  <button id=\"rec\" type=\"button\" title=\"Record the live stream to a .jsonl file that replay.mjs can play\">● Record</button>\n  <div id=\"conn\">connecting…</div>\n</header>\n<main>\n  <section class=\"panel\" id=\"talk-panel\"><h2>Conversation</h2><div class=\"scroll\" id=\"talk\"><p class=\"empty\">Nothing said yet</p></div></section>\n  <section class=\"panel\" id=\"plan-panel\"><h2>Plan</h2><div class=\"scroll\" id=\"plan\"><p class=\"empty\">No plan yet</p></div></section>\n  <section class=\"panel\" id=\"phone-panel\"><div class=\"phone\" id=\"phone\">\n    <div class=\"app\" id=\"phone-app\">Phone</div>\n    <div class=\"screen\" id=\"phone-screen\"><div class=\"empty-screen\">Waiting for the first screen read</div></div>\n    <div class=\"cursor\" id=\"phone-cursor\"><img src=\"data:image/svg+xml;base64,\" alt=\"\"></div>\n  </div></section>\n  <div id=\"side\">\n    <section class=\"panel\" id=\"call-panel\" hidden><h2>Phone call</h2><div id=\"call\"></div></section>\n    <section class=\"panel\" id=\"feed-panel\"><h2>Phone</h2><div class=\"scroll\" id=\"feed\"><p class=\"empty\">No actions yet</p></div></section>\n    <section class=\"panel\" id=\"sync-panel\" hidden><h2>Voice ↔ cursor</h2>\n      <p class=\"sync-legend\"><b class=\"v\">■</b> voice &nbsp;<b class=\"c\">■</b> cursor &nbsp;· seconds from voice start to tap done (green ≤ 1.5 s)</p>\n      <div id=\"sync\"></div></section>\n  </div>\n</main>\n<script>\n\"use strict\";\nconst params = new URLSearchParams(location.search);\n// Inside the Bobby app there is no URL query: the app injects window.BOBBY_HUB = {hub, token} instead.\nconst embed = (typeof window.BOBBY_HUB === \"object\" && window.BOBBY_HUB) || {};\nif (embed.hub) document.documentElement.classList.add(\"in-app\");\nconst hub = (embed.hub || params.get(\"hub\") || \"ws://localhost:8765\").replace(/\\/+$/, \"\");\nconst hubUrl = (/^wss?:\\/\\//.test(hub) ? hub : \"ws://\" + hub) + \"/watch?token=\" + encodeURIComponent(embed.token || params.get(\"token\") || \"\");\nif (params.get(\"theme\")) document.documentElement.dataset.theme = params.get(\"theme\");\n\nconst $ = (id) => document.getElementById(id);\nconst handlers = {};            // type -> fn(msg), filled in below\nfunction handle(msg) {\n  record(msg);\n  const fn = handlers[msg.type];\n  if (fn) { try { fn(msg); } catch (e) { console.error(\"handler\", msg.type, e); } }\n}\n\n// Connection: hello, then every frame goes to handle(). Reconnect 1 s, 2 s, 5 s, then every 5 s.\nconst backoff = [1000, 2000, 5000];\nlet tries = 0;\nfunction setConn(text, cls) { const el = $(\"conn\"); el.textContent = text; el.className = cls || \"\"; }\nfunction connect() {\n  setConn(\"connecting…\");\n  let ws;\n  try { ws = new WebSocket(hubUrl); } catch (e) { return retry(); }\n  ws.onopen = () => ws.send(JSON.stringify({ type: \"hello\", role: \"watch\", v: 1 }));\n  ws.onmessage = (e) => {\n    let msg; try { msg = JSON.parse(e.data); } catch { return; }\n    if (msg.type === \"welcome\") { tries = 0; setConn(\"live\", \"live\"); return; }\n    handle(msg);\n  };\n  ws.onclose = (e) => {\n    if (e.code === 4003) setConn(\"wrong token\", \"down\");\n    retry();\n  };\n}\nfunction retry() {\n  const wait = backoff[Math.min(tries++, backoff.length - 1)];\n  if ($(\"conn\").textContent !== \"wrong token\") setConn(\"reconnecting in \" + wait / 1000 + \" s\", \"down\");\n  setTimeout(connect, wait);\n}\n// ---------- helpers ----------\nfunction el(tag, cls, text) {\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text != null) e.textContent = text;\n  return e;\n}\nfunction clearEmpty(box) { box.querySelectorAll(\":scope > .empty\").forEach((e) => e.remove()); }\nfunction stickToBottom(box, add) {\n  const atBottom = box.scrollHeight - box.scrollTop - box.clientHeight < 80;\n  add();\n  if (atBottom) box.scrollTop = box.scrollHeight;\n}\n\n// ---------- conversation ----------\nfunction addLine(kind, who, text) {\n  const box = $(\"talk\");\n  clearEmpty(box);\n  stickToBottom(box, () => {\n    const line = el(\"div\", \"line \" + kind);\n    if (who) line.append(el(\"span\", \"who\", who));\n    line.append(document.createTextNode(text));\n    box.append(line);\n    while (box.children.length > 60) box.firstChild.remove();\n  });\n}\n\n// ---------- task + plan ----------\nlet plan = { task: null, steps: [], status: {} };   // status: n -> running|done|failed\nfunction setTask(m) {\n  const t = $(\"task-title\");\n  t.textContent = m.title || m.task;\n  t.className = \"\";\n  const b = $(\"task-status\");\n  b.textContent = m.status;\n  b.className = \"badge \" + m.status;\n}\nfunction renderPlan(changed = new Set(), note = \"\") {\n  const box = $(\"plan\");\n  box.textContent = \"\";\n  if (!plan.steps.length) { box.append(el(\"p\", \"empty\", \"No plan yet\")); return; }\n  if (note) box.append(el(\"p\", \"plan-note\", note));\n  const ol = el(\"ol\");\n  for (const s of plan.steps) {\n    const st = plan.status[s.n] || \"pending\";\n    const li = el(\"li\", \"step \" + st + (changed.has(s.n) ? \" changed\" : \"\"));\n    li.dataset.n = s.n;\n    li.append(el(\"div\", \"mark\", st === \"done\" ? \"✓\" : st === \"failed\" ? \"✕\" : String(s.n)));\n    const body = el(\"div\");\n    body.append(el(\"div\", \"do\", s.do));\n    if (s.why) body.append(el(\"div\", \"why\", s.why));\n    li.append(body);\n    ol.append(li);\n  }\n  box.append(ol);\n  const running = box.querySelector(\".step.running\");\n  if (running) running.scrollIntoView({ block: \"nearest\", behavior: \"smooth\" });\n}\n\nhandlers.task = (m) => {\n  setTask(m);\n  if (m.status === \"started\" && m.task !== plan.task) { plan = { task: m.task, steps: [], status: {} }; renderPlan(); }\n};\nhandlers.plan = (m) => {\n  const steps = m.steps || [];\n  let changed = new Set(), note = \"\";\n  if (m.task === plan.task && plan.steps.length) {\n    const old = new Map(plan.steps.map((s) => [s.n, s.do + \"|\" + s.why]));\n    for (const s of steps) if (old.get(s.n) !== s.do + \"|\" + s.why) changed.add(s.n);\n    if (changed.size) note = \"Plan changed\";\n  } else if (m.task !== plan.task) {\n    plan = { task: m.task, steps: [], status: {} };\n  }\n  plan.steps = steps;\n  renderPlan(changed, note);\n};\nhandlers.step = (m) => {\n  if (m.task !== plan.task) return;\n  plan.status[m.n] = m.status;\n  renderPlan();\n};\n\n// ---------- wire: frames between the parts ----------\nconst wire = {};   // msg.type -> fn(msg, frame)\nhandlers.wire = (f) => {\n  const m = f.msg || {};\n  const fn = wire[m.type];\n  if (fn) { try { fn(m, f); } catch (e) { console.error(\"wire\", m.type, e); } }\n};\nwire.heard = (m) => addLine(\"you\", \"You\", m.text);\nwire.spoke = (m) => addLine(\"bobby\", \"Bobby\", m.text);\nwire.wake = () => addLine(\"sys\", \"\", \"Bobby is listening\");\nwire.asleep = () => addLine(\"sys\", \"\", \"Bobby went to sleep\");\n\n// ---------- peers ----------\nconst PEERS = [[\"hands\", \"Hands\"], [\"mind\", \"Mind\"], [\"mouth\", \"Mouth\"], [\"caller\", \"Caller\"]];\nhandlers.peers = (m) => {\n  const box = $(\"peers\");\n  box.textContent = \"\";\n  for (const [key, label] of PEERS) {\n    const p = el(\"div\", \"peer\" + (m[key] ? \" on\" : \"\"));\n    p.title = label + (m[key] ? \" connected\" : \" not connected\");\n    p.append(el(\"span\", \"dot\"), document.createTextNode(label));\n    box.append(p);\n  }\n};\n\n// ---------- phone feed ----------\nfunction targetWords(on) {\n  if (!on) return \"\";\n  if (on.text != null) return \"“\" + on.text + \"”\";\n  if (on.n != null) return \"item \" + on.n;\n  if (on.x != null) return \"(\" + on.x + \", \" + on.y + \")\";\n  return \"\";\n}\nfunction actWords(m) {\n  const t = targetWords(m.on);\n  switch (m.do) {\n    case \"tap\": return \"Tap \" + t;\n    case \"long_press\": return \"Long-press \" + t;\n    case \"point\": return \"Point at \" + t;\n    case \"type\": return \"Type “\" + (m.text || \"\") + \"”\";\n    case \"swipe\": return \"Swipe \" + (m.dir || \"\") + (t ? \" on \" + t : \"\");\n    case \"key\": return { home: \"Go home\", back: \"Go back\", recents: \"Open recent apps\",\n      notifications: \"Open notifications\", enter: \"Press Enter\" }[m.name] || \"Press \" + m.name;\n    case \"launch\": return \"Open \" + (m.app || \"app\");\n    case \"wait\": return \"Wait \" + ((m.ms || 0) / 1000) + \" s\";\n    default: return m.do || \"Action\";\n  }\n}\nconst acts = new Map();   // act id -> feed row\nfunction addFeed(row) {\n  const box = $(\"feed\");\n  clearEmpty(box);\n  stickToBottom(box, () => {\n    box.append(row);\n    while (box.children.length > 80) box.firstChild.remove();\n  });\n}\nfunction feedRow(cls, mark, text) {\n  const row = el(\"div\", \"act \" + cls);\n  row.append(el(\"span\", \"res\", mark), el(\"span\", \"what\", text));\n  return row;\n}\nwire.act = (m) => {\n  const row = feedRow(\"pending\", \"…\", actWords(m));\n  acts.set(m.id, row);\n  addFeed(row);\n};\nwire.act_result = (m) => {\n  const row = acts.get(m.re);\n  if (!row) return;\n  acts.delete(m.re);\n  row.className = \"act \" + (m.ok ? \"ok\" : \"fail\");\n  row.querySelector(\".res\").textContent = m.ok ? \"✓\" : \"✕\";\n  if (!m.ok) row.querySelector(\".what\").dataset.err = m.error || \"failed\";\n};\nwire.screen = () => addFeed(feedRow(\"note\", \"◎\", \"Reading the screen\"));\nwire.notification = (m) => addFeed(feedRow(\"note\", \"🔔\", (m.title ? m.title + \": \" : \"\") + (m.text || \"\")));\n\n// ---------- call ----------\nconst CALL_WORDS = { dialing: \"Dialing…\", answered: \"On the call\", ended: \"Call ended\", failed: \"Call failed\" };\nlet callNumber = \"\";\nfunction callPanel() { $(\"call-panel\").hidden = false; return $(\"call\"); }\nwire.call = (m) => {\n  callNumber = m.number || \"\";\n  const box = callPanel();\n  box.textContent = \"\";\n  box.append(el(\"div\", \"status\", \"Starting call…\"), el(\"div\", \"number\", callNumber));\n  if (m.goal) box.append(el(\"div\", \"number\", \"Goal: \" + m.goal));\n};\nwire.call_status = (m) => {\n  const box = callPanel();\n  let s = box.querySelector(\".status\");\n  if (!s) { s = el(\"div\", \"status\"); box.prepend(s); }\n  s.textContent = CALL_WORDS[m.status] || m.status;\n  s.className = \"status\" + (m.status === \"dialing\" || m.status === \"answered\" ? \" live\" : \"\");\n};\nwire.call_result = (m) => {\n  const box = callPanel();\n  box.querySelector(\".summary\")?.remove();\n  box.querySelector(\".tx\")?.remove();\n  const s = box.querySelector(\".status\") || box.appendChild(el(\"div\", \"status\"));\n  s.className = \"status\";\n  s.textContent = m.ok ? \"Call ended\" : \"Call failed\";\n  box.append(el(\"div\", \"summary\" + (m.ok ? \"\" : \" failed\"), m.ok ? m.summary : \"Didn't get through: \" + (m.error || \"failed\")));\n  if (Array.isArray(m.transcript) && m.transcript.length) {\n    const tx = el(\"div\", \"tx\");\n    for (const t of m.transcript) {\n      const line = el(\"div\");\n      line.append(el(\"b\", null, t.who === \"me\" ? \"Bobby: \" : \"Them: \"), document.createTextNode(t.text));\n      tx.append(line);\n    }\n    box.append(tx);\n  }\n};\n\n// ---------- voice-cursor sync strip (experiment) ----------\n// The Mind sends each step's `say` and `act` at the same instant. For each pair this shows when\n// Bobby's voice started (say_started) and when the cursor's action finished (act_result), so the\n// team can see whether voice and cursor land together. Uses the hub's `at` stamps.\nconst sync = { lastSay: null, bySay: new Map(), byAct: new Map(), rows: [] };\nconst SYNC_SPAN_MS = 4000;     // width of the bar\nconst SYNC_GOOD_MS = 1500;     // voice start and cursor finish within this count as in sync\nfunction syncRender(p) {\n  if (!p.row) {\n    $(\"sync-panel\").hidden = false;\n    p.row = el(\"div\", \"sync-row\");\n    p.row.append(el(\"span\", \"label\", p.label), el(\"div\", \"sync-bar\"), el(\"span\", \"gap\", \"…\"));\n    const box = $(\"sync\");\n    box.prepend(p.row);\n    while (box.children.length > 5) box.lastChild.remove();\n  }\n  const bar = p.row.querySelector(\".sync-bar\");\n  bar.textContent = \"\";\n  const pct = (ms) => Math.max(0, Math.min(100, (ms / SYNC_SPAN_MS) * 100)) + \"%\";\n  if (p.voiceAt != null) {\n    const v = el(\"i\", \"voice\");\n    v.style.left = pct(p.voiceAt - p.t0);\n    v.style.width = \"calc(100% - \" + pct(p.voiceAt - p.t0) + \")\";\n    if (p.voiceEnd != null) v.style.width = pct(p.voiceEnd - p.voiceAt);\n    bar.append(v);\n  }\n  const c = el(\"i\", \"cursor\");\n  c.style.left = pct(p.actAt - p.t0);\n  c.style.width = p.resAt != null ? pct(p.resAt - p.actAt) : \"4px\";\n  c.style.top = \"6px\"; c.style.height = \"6px\";\n  bar.append(c);\n  if (p.voiceAt != null && p.resAt != null) {\n    const gap = p.resAt - p.voiceAt;\n    p.row.className = \"sync-row \" + (Math.abs(gap) <= SYNC_GOOD_MS ? \"good\" : \"off\");\n    p.row.querySelector(\".gap\").textContent = (gap >= 0 ? \"+\" : \"\") + (gap / 1000).toFixed(1);\n    p.row.title = \"voice started \" + ((p.voiceAt - p.t0) / 1000).toFixed(2) + \" s after the say; cursor finished \" +\n      ((p.resAt - p.t0) / 1000).toFixed(2) + \" s after\";\n  }\n}\nconst at = (f) => (f && f.at) || Date.now();\nwire.say = (m, f) => { sync.lastSay = { id: m.id, at: at(f) }; };\nwire.say_started = (m, f) => {\n  const p = sync.bySay.get(m.re);\n  if (p) { p.voiceAt = at(f); syncRender(p); }\n};\nwire.say_done = (m, f) => {\n  const p = sync.bySay.get(m.re);\n  if (p) { p.voiceEnd = at(f); syncRender(p); sync.bySay.delete(m.re); }\n};\n{\n  const showAct = wire.act, showResult = wire.act_result;\n  wire.act = (m, f) => {\n    showAct(m, f);\n    const t = at(f);\n    const s = sync.lastSay;\n    if (!s || t - s.at > 400) return;          // no say sent with this act\n    sync.lastSay = null;\n    const p = { label: actWords(m), t0: s.at, actAt: t };\n    sync.bySay.set(s.id, p);\n    sync.byAct.set(m.id, p);\n    syncRender(p);\n  };\n  wire.act_result = (m, f) => {\n    showResult(m, f);\n    const p = sync.byAct.get(m.re);\n    if (p) { p.resAt = at(f); syncRender(p); sync.byAct.delete(m.re); }\n  };\n}\n\n// ---------- phone panel (experiment) ----------\n// Draws the latest screen_result and moves the cursor to each act's target, resolved the way\n// the contract says Hands does it: {n}, {text} (exact beats contains, text or desc), or {x,y}.\n// ?phone=0 hides the panel. ?cursor=<name> picks a design from stage/cursor/ (default ring).\nif (params.get(\"phone\") === \"0\") document.body.classList.add(\"no-phone\");\nif (params.get(\"cursor\")) {\n  const c = params.get(\"cursor\").replace(/[^a-z0-9_-]/gi, \"\");\n  $(\"phone-cursor\").querySelector(\"img\").src = \"../cursor/\" + c + \"/\" + c + \".svg\";\n}\nconst APP_NAMES = { \"com.google.android.gm\": \"Gmail\", \"com.sec.android.app.launcher\": \"Home screen\",\n  \"com.whatsapp\": \"WhatsApp\", \"com.android.chrome\": \"Chrome\", \"com.google.android.apps.maps\": \"Maps\",\n  \"com.spotify.music\": \"Spotify\", \"com.android.settings\": \"Settings\", \"com.samsung.android.messaging\": \"Messages\",\n  \"com.google.android.apps.messaging\": \"Messages\" };\nconst phone = { size: [1080, 2400], nodes: [], hideTimer: 0 };\nfunction pct(v, total) { return (100 * v / total) + \"%\"; }\nfunction drawScreen(m) {\n  phone.size = Array.isArray(m.size) && m.size.length === 2 ? m.size : [1080, 2400];\n  phone.nodes = Array.isArray(m.nodes) ? m.nodes : [];\n  $(\"phone\").style.aspectRatio = phone.size[0] + \" / \" + phone.size[1];\n  $(\"phone-app\").textContent = APP_NAMES[m.app] || m.app || \"Phone\";\n  const scr = $(\"phone-screen\");\n  scr.textContent = \"\";\n  scr.classList.remove(\"stale\");\n  // Hands adds a real screenshot (\"image\", base64 JPEG) when the Mind asks for one: draw it behind the labels.\n  const img = typeof m.image === \"string\" && m.image.length > 100 ? m.image : \"\";\n  scr.classList.toggle(\"has-image\", !!img);\n  scr.style.backgroundImage = img ? \"url(data:image/jpeg;base64,\" + img + \")\" : \"\";\n  const [W, H] = phone.size;\n  for (const n of phone.nodes) {\n    if (!Array.isArray(n.bounds)) continue;\n    const [l, t, r, b] = n.bounds;\n    const d = el(\"div\", \"node\" + (n.tap ? \" tap\" : \"\") + (n.edit ? \" edit\" : \"\") + (!n.text && !n.desc && n.hint ? \" hint\" : \"\"), n.text || n.desc || n.hint || \"\");\n    d.dataset.n = n.n;\n    Object.assign(d.style, { left: pct(l, W), top: pct(t, H), width: pct(r - l, W), height: pct(b - t, H) });\n    scr.append(d);\n  }\n  if (!phone.nodes.length) scr.append(el(\"div\", \"empty-screen\", \"Nothing readable on screen\"));\n  requestAnimationFrame(fitLabels);\n}\n// A label that doesn't fit its box (a small icon button) is shown as a caption under the box instead.\nfunction fitLabels() {\n  const scr = $(\"phone-screen\");\n  scr.querySelectorAll(\".cap\").forEach((c) => c.remove());\n  const sw = scr.clientWidth, placed = [];\n  if (scr.classList.contains(\"has-image\")) return;\n  for (const d of scr.querySelectorAll(\".node\")) {\n    d.classList.remove(\"tiny\");\n    if (!d.textContent) continue;\n    if (d.scrollWidth <= d.clientWidth + 1 && d.scrollHeight <= d.clientHeight + 1) continue;\n    d.classList.add(\"tiny\");\n    const cap = el(\"div\", \"cap\", d.textContent);\n    scr.append(cap);\n    const w = cap.offsetWidth, h = cap.offsetHeight;\n    // centred under the box, kept inside the screen, moved down until it overlaps no other caption\n    let x = Math.min(Math.max(d.offsetLeft + d.offsetWidth / 2, w / 2 + 2), sw - w / 2 - 2);\n    let y = d.offsetTop + d.offsetHeight + 3;\n    const hits = (r) => placed.some((q) => r.l < q.r && r.r > q.l && r.t < q.b && r.b > q.t);\n    let r = { l: x - w / 2, r: x + w / 2, t: y, b: y + h };\n    while (hits(r)) { y += h + 2; r = { l: r.l, r: r.r, t: y, b: y + h }; }\n    placed.push(r);\n    cap.style.left = x + \"px\"; cap.style.top = y + \"px\";\n  }\n}\naddEventListener(\"resize\", () => requestAnimationFrame(fitLabels));\nfunction findNode(on) {\n  if (!on) return null;\n  if (on.n != null) return phone.nodes.find((n) => n.n === on.n) || null;\n  if (on.text != null) {\n    const q = String(on.text).toLowerCase();\n    const label = (n) => [(n.text || \"\").toLowerCase(), (n.desc || \"\").toLowerCase(), (n.hint || \"\").toLowerCase()];   // Hands matches hint after text/desc\n    return phone.nodes.find((n) => label(n).includes(q)) || phone.nodes.find((n) => label(n).some((s) => s.includes(q))) || null;\n  }\n  return null;\n}\nfunction targetPoint(on) {          // -> {x, y} in screen pixels, or null\n  if (on && on.x != null && on.y != null) return { x: on.x, y: on.y };\n  const n = findNode(on);\n  if (n && Array.isArray(n.bounds)) return { x: (n.bounds[0] + n.bounds[2]) / 2, y: (n.bounds[1] + n.bounds[3]) / 2, node: n };\n  return null;\n}\nfunction moveCursor(p) {\n  const c = $(\"phone-cursor\");\n  c.classList.add(\"on\");\n  c.style.left = pct(p.x, phone.size[0]);\n  c.style.top = pct(p.y, phone.size[1]);\n  clearTimeout(phone.hideTimer);\n}\nfunction hideCursorSoon() {          // Hands shows the cursor during an act and for 2 s after\n  clearTimeout(phone.hideTimer);\n  phone.hideTimer = setTimeout(() => $(\"phone-cursor\").classList.remove(\"on\"), 2000);\n}\nfunction chip(text) {\n  $(\"phone\").querySelectorAll(\".chip\").forEach((c) => c.remove());\n  const c = el(\"div\", \"chip\", text);\n  $(\"phone\").append(c);\n  setTimeout(() => c.remove(), 2200);\n}\nfunction ripple(p) {\n  const r = el(\"div\", \"ripple\");\n  r.style.left = pct(p.x, phone.size[0]);\n  r.style.top = pct(p.y, phone.size[1]);\n  $(\"phone\").append(r);\n  setTimeout(() => r.remove(), 700);\n}\nconst SWIPE = { left: [0.8, 0.5, 0.2, 0.5], right: [0.2, 0.5, 0.8, 0.5], up: [0.5, 0.75, 0.5, 0.3], down: [0.5, 0.3, 0.5, 0.75] };\nconst phoneActs = new Map();         // act id -> {do, point}\nfunction phoneAct(m) {\n  const [W, H] = phone.size;\n  let point = null;\n  $(\"phone-screen\").querySelectorAll(\".node.hit\").forEach((n) => n.classList.remove(\"hit\"));\n  if ([\"tap\", \"long_press\", \"point\"].includes(m.do) || (m.do === \"type\" && m.on)) {\n    point = targetPoint(m.on);\n    if (point) {\n      moveCursor(point);\n      if (point.node) $(\"phone-screen\").querySelector('.node[data-n=\"' + point.node.n + '\"]')?.classList.add(\"hit\");\n    } else {\n      moveCursor({ x: W / 2, y: H * 0.55 });   // target isn't in the last screen read: show where it's headed\n    }\n    chip(actWords(m));\n  } else if (m.do === \"swipe\") {\n    const s = SWIPE[m.dir] || SWIPE.left;\n    const from = targetPoint(m.on) || { x: s[0] * W, y: s[1] * H };\n    const c = $(\"phone-cursor\");\n    c.style.transition = \"none\";\n    moveCursor(from);\n    void c.offsetWidth;                          // restart the transition from the swipe's start point\n    c.style.transition = \"\";\n    setTimeout(() => moveCursor({ x: from.x + (s[2] - s[0]) * W, y: from.y + (s[3] - s[1]) * H }), 30);\n    chip(actWords(m));\n  } else if (m.do === \"type\") {\n    chip(\"⌨ \" + (m.text || \"\"));\n  } else {\n    chip(actWords(m));\n  }\n  phoneActs.set(m.id, { do: m.do, point });\n}\nfunction phoneResult(m) {\n  const a = phoneActs.get(m.re);\n  if (!a) return;\n  phoneActs.delete(m.re);\n  if (m.ok && a.point && (a.do === \"tap\" || a.do === \"long_press\")) ripple(a.point);\n  if (!m.ok) chip(\"✕ \" + (m.error || \"failed\"));\n  // After anything that can change the screen, the drawn screen is out of date until the next read.\n  if (m.ok && a.do !== \"point\" && a.do !== \"wait\") $(\"phone-screen\").classList.add(\"stale\");\n  hideCursorSoon();\n}\n{\n  const prevAct = wire.act, prevResult = wire.act_result, prevScreenResult = wire.screen_result;\n  wire.act = (m, f) => { prevAct && prevAct(m, f); try { phoneAct(m); } catch (e) { console.error(\"phone act\", e); } };\n  wire.act_result = (m, f) => { prevResult && prevResult(m, f); try { phoneResult(m); } catch (e) { console.error(\"phone result\", e); } };\n  wire.screen_result = (m, f) => { prevScreenResult && prevScreenResult(m, f); drawScreen(m); };\n  const prevCursor = wire.cursor;\n  wire.cursor = (m, f) => {\n    prevCursor && prevCursor(m, f);\n    if (m.show === false) { clearTimeout(phone.hideTimer); $(\"phone-cursor\").classList.remove(\"on\"); }\n  };\n}\n\n// ---------- record button (experiment) ----------\n// Saves every watch message received while recording, one per line with a \"dt\" (ms since the\n// previous line), in the story.jsonl format: `node dashboard/replay.mjs --story <file>` plays it back.\nconst rec = { on: false, lines: [], last: 0 };\nfunction record(msg) {\n  if (!rec.on || msg.type === \"welcome\") return;\n  const now = Date.now();\n  rec.lines.push(JSON.stringify({ ...msg, dt: rec.lines.length ? now - rec.last : 0 }));\n  rec.last = now;\n  $(\"rec\").textContent = \"■ Stop (\" + rec.lines.length + \")\";\n}\n$(\"rec\").addEventListener(\"click\", () => {\n  const b = $(\"rec\");\n  if (!rec.on) {\n    rec.on = true; rec.lines = []; rec.last = Date.now();\n    b.classList.add(\"on\"); b.textContent = \"■ Stop (0)\";\n    return;\n  }\n  rec.on = false;\n  b.classList.remove(\"on\"); b.textContent = \"● Record\";\n  if (!rec.lines.length) return;\n  const blob = new Blob([rec.lines.join(\"\\n\") + \"\\n\"], { type: \"application/x-ndjson\" });\n  const a = document.createElement(\"a\");\n  a.href = URL.createObjectURL(blob);\n  a.download = \"bobby-\" + new Date().toISOString().slice(0, 19).replace(/[:T]/g, \"-\") + \".jsonl\";\n  document.body.append(a); a.click(); a.remove();\n  setTimeout(() => URL.revokeObjectURL(a.href), 1000);\n});\n\nconnect();\n</script>\n</body>\n</html>\n";
